// crypto/mlsGroup.ts
//
// Real MLS group client built on `ts-mls` (RFC 9420, pure-TypeScript, no WASM).
// PQC ciphersuite by default (ML-KEM768) for post-quantum forward secrecy.
//
// "Mourn layer" parity with 1:1 messaging:
//   - Each MLS leaf's signature key is bound to the device's long-term Ed25519
//     identity key (the same identity key used by the 1:1 Vault). This makes
//     every group member cryptographically verifiable instead of relying on a
//     throwaway key generated by the library.
//   - Credentials are validated (see makeCredentialValidator) against the known
//     member roster so a mismatched/unknown leaf is rejected instead of trusted.
//   - Safety numbers are provided for out-of-band member verification, mirroring
//     KeyManager.generateSafetyNumber.
//
// TRUST MODEL: the server is zero-trust. It only ever stores/relays opaque
// blobs (encoded ClientState tree, Commit messages, Welcome messages). The
// server NEVER sees plaintext and cannot decrypt — all key material stays on
// the client and is encrypted-at-rest locally.

import sodium from 'libsodium-wrappers';
import {
  type ClientState,
  type KeyPackage,
  type PrivateKeyPackage,
  type CiphersuiteImpl,
  type Credential,
  type Capabilities,
  type Lifetime,
  type Extension,
  type ClientConfig,
  type PrivateMessage,
  type MLSMessage,
  type MlsKeyPackage,
  type MlsWelcome,
  type MlsPrivateMessage,
  type RatchetTree,
  type Node,
  type AuthenticationService,
  getCiphersuiteFromName,
  getCiphersuiteImpl,
  ciphersuites,
  nobleCryptoProvider,
  emptyPskIndex,
  generateKeyPackage,
  generateKeyPackageWithKey,
  createGroup,
  joinGroup,
  createApplicationMessage,
  processPrivateMessage,
  processPublicMessage,
  createCommit,
  encodeGroupState,
  decodeGroupState,
  encodeMlsMessage,
  decodeMlsMessage,
  defaultPaddingConfig,
  defaultKeyRetentionConfig,
  defaultLifetimeConfig,
  defaultKeyPackageEqualityConfig,
  defaultAuthenticationService,
} from 'ts-mls';

// PQC ciphersuite: ML-KEM768 + ChaCha20-Poly1305 + SHA384 + Ed25519.
// ChaCha20-Poly1305 is used instead of AES-256-GCM for parity with the 1:1
// vault (XChaCha20-Poly1305) and for constant-time performance on mobile/ARM
// hardware without AES-NI. It provides equivalent AEAD security (256-bit key,
// 128-bit security level) and is an IETF-registered MLS ciphersuite.
export const CIPHERSUITE_NAME = 'MLS_256_MLKEM768_CHACHA20POLY1305_SHA384_Ed25519' as const;

/**
 * The suite every group created BEFORE the ChaCha20 switch was built with.
 *
 * An MLS group's ciphersuite is fixed for the lifetime of the group, so a group
 * created under AES-256-GCM must keep being driven by the AES-256-GCM impl
 * forever — including after the app updates. Re-decoding such state with the
 * build's current default is what made "old suites stop working after an
 * update", so this name is retained and persisted alongside each group's state.
 */
export const LEGACY_CIPHERSUITE_NAME = 'MLS_256_MLKEM768_AES256GCM_SHA384_Ed25519' as const;

/**
 * A long-term Ed25519 signing key pair (e.g. the device identity key), in
 * libsodium format: `signKey` is the 64-byte private key (seed ‖ public key)
 * and `publicKey` is the 32-byte public key.
 */
export interface MlsIdentityKeyPair {
  /** Ed25519 private key (64-byte libsodium `crypto_sign` format). */
  signKey: Uint8Array;
  /** Ed25519 public key (32 bytes). */
  publicKey: Uint8Array;
}

/**
 * Convert a libsodium-format Ed25519 key pair to the shape `ts-mls`/noble
 * expects: the 32-byte seed as `signKey` and the raw 32-byte public key. The
 * 64-byte libsodium private key is `seed(32) ‖ publicKey(32)`.
 */
function toMlsSignatureKey(identityKeyPair: MlsIdentityKeyPair): {
  signKey: Uint8Array;
  publicKey: Uint8Array;
} {
  const seed =
    identityKeyPair.signKey.length === 64
      ? identityKeyPair.signKey.slice(0, 32)
      : identityKeyPair.signKey;
  return { signKey: seed, publicKey: identityKeyPair.publicKey };
}

function bytesToBase64(bytes: Uint8Array): string {
  let bin = '';
  const len = bytes.length ?? 0;
  for (let i = 0; i < len; i++) bin += String.fromCharCode(bytes[i] ?? 0);
  return btoa(bin);
}

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const len = bin.length ?? 0;
  const out = new Uint8Array(len);
  for (let i = 0; i < len; i++) out[i] = bin.charCodeAt(i) ?? 0;
  return out;
}

function decodeMls(bytes: Uint8Array): MLSMessage {
  const res = decodeMlsMessage(bytes, 0);
  if (!res) throw new Error('mls: failed to decode MLS message');
  return res[0];
}

/** Constant-time-ish byte-array equality (used to match a leaf credential id). */
function identityEquals(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= (a[i] ?? 0) ^ (b[i] ?? 0);
  return diff === 0;
}

// ---------------------------------------------------------------------------
// Shared MLS parameter builders (used by both the store and the test harness).
// Identity is a device id (a stable non-secret routing identifier). The real
// cryptographic authentication comes from binding the leaf's signature key to
// the device's Ed25519 identity key and validating it (see makeCredentialValidator).
// ---------------------------------------------------------------------------

/** A Basic credential carrying the device id as the identifier. */
export function mlsCredential(deviceId: string): Credential {
  return { credentialType: 'basic', identity: new TextEncoder().encode(deviceId) };
}

/** Capabilities: support the PQC ciphersuite + all default proposals. */
export function mlsCapabilities(): Capabilities {
  return {
    versions: ['mls10'],
    ciphersuites: [CIPHERSUITE_NAME],
    extensions: [],
    proposals: [1, 2, 3], // add, update, remove
    credentials: ['basic'],
  };
}

/** Lifetime: valid for ~10 years (groups are long-lived; rotation via commits). */
export function mlsLifetime(): Lifetime {
  const now = Math.floor(Date.now() / 1000);
  return {
    notBefore: BigInt(now - 60),
    notAfter: BigInt(now + 60 * 60 * 24 * 365 * 10),
  };
}

/** Group context extensions (none required for the basic group profile). */
export function mlsExtensions(): Extension[] {
  return [];
}

/**
 * Build a ClientConfig compatible with ts-mls. Accepts an optional
 * AuthenticationService so group members can enforce credential/identity
 * validation (the "mourn layer"). When omitted, ts-mls' accept-all default is
 * used (backwards compatible with the test harness).
 */
export function mlsClientConfig(authService?: AuthenticationService): ClientConfig {
  return {
    keyRetentionConfig: defaultKeyRetentionConfig,
    lifetimeConfig: defaultLifetimeConfig,
    keyPackageEqualityConfig: defaultKeyPackageEqualityConfig,
    paddingConfig: defaultPaddingConfig,
    authService: authService ?? defaultAuthenticationService,
  };
}

/**
 * Build a credential validator from the known member roster.
 *
 * `expectedIdentityByDeviceId` maps a device id to its expected Ed25519
 * identity public key (lowercase hex). A leaf is accepted only when its
 * credential identity (device id) is known AND its signature public key equals
 * the expected identity key. This closes the "server silently injects an
 * attacker key package" hole — the server can still misreport the roster, but
 * that residual risk is addressed by out-of-band safety numbers.
 */
export function makeCredentialValidator(
  expectedIdentityByDeviceId: Map<string, string>,
): AuthenticationService {
  return {
    async validateCredential(credential, signaturePublicKey) {
      if (credential.credentialType !== 'basic') return false;
      const deviceId = new TextDecoder().decode(credential.identity);
      const expected = expectedIdentityByDeviceId.get(deviceId);
      if (!expected) return false;
      const actual = sodium.to_hex(signaturePublicKey).toLowerCase();
      return actual === expected.toLowerCase();
    },
  };
}

/** Stable group id bytes from a server uuid (non-secret, UTF-8 encoded). */
export function mlsGroupIdBytes(groupId: string): Uint8Array {
  return new TextEncoder().encode(groupId);
}

/**
 * True when `name` is a ciphersuite this build of ts-mls can actually
 * implement. Guards the cast into ts-mls's `CiphersuiteName` union so a
 * corrupted/unknown name from local storage degrades to the current default
 * instead of throwing or silently mis-decoding.
 */
export function isKnownCiphersuite(name: unknown): name is keyof typeof ciphersuites {
  return typeof name === 'string' && Object.prototype.hasOwnProperty.call(ciphersuites, name);
}

/**
 * Resolve a ciphersuite implementation, defaulting to the current build default.
 *
 * Pass the suite PERSISTED WITH A GROUP'S STATE whenever the state came from
 * local storage — an MLS group keeps its original ciphersuite for life, so
 * loading an AES-era group with the ChaCha20 impl breaks it.
 */
export async function mlsCiphersuite(name?: unknown): Promise<CiphersuiteImpl> {
  const resolved = isKnownCiphersuite(name) ? name : CIPHERSUITE_NAME;
  const suite = getCiphersuiteFromName(resolved);
  return getCiphersuiteImpl(suite, nobleCryptoProvider);
}

/**
 * Safety number for out-of-band group-member verification. Mirrors the 1:1
 * `KeyManager.generateSafetyNumber` exactly: SHA-512(sortedPub_A ‖ sortedPub_B)
 * with 5 rounds of iterated hashing, then the first 30 bytes are formatted as
 * 12 groups of 5 decimal digits. Identical regardless of call order.
 */
export async function generateGroupSafetyNumber(
  aIdentityPub: Uint8Array,
  bIdentityPub: Uint8Array,
): Promise<string> {
  await sodium.ready;
  const cmp = sodium.compare(aIdentityPub, bIdentityPub);
  const first = cmp <= 0 ? aIdentityPub : bIdentityPub;
  const second = cmp <= 0 ? bIdentityPub : aIdentityPub;

  const combined = new Uint8Array(first.length + second.length);
  combined.set(first, 0);
  combined.set(second, first.length);

  let hash = sodium.crypto_generichash(64, combined, null);
  for (let i = 0; i < 4; i++) {
    hash = sodium.crypto_generichash(64, hash, null);
  }

  const digits: string[] = [];
  for (let i = 0; i < 30; i++) {
    digits.push(String((hash[i] as number) % 100).padStart(2, '0'));
  }
  const raw = digits.join('');
  const blocks: string[] = [];
  for (let i = 0; i < 60; i += 5) {
    blocks.push(raw.slice(i, i + 5));
  }
  return blocks.join(' ');
}

export interface MlsKeyPackagePair {
  publicPackageB64: string; // wire format sent to peers/server
  privatePackage: PrivateKeyPackage; // LOCAL only, never transmitted
}

/**
 * One device's view of a single MLS group. Wraps ClientState + ciphersuite so
 * the rest of the app never touches ts-mls types directly.
 */
export class MlsGroupClient {
  private constructor(
    private state: ClientState,
    private cs: CiphersuiteImpl,
  ) {}

  /** Epoch (number) derived from the group context, for drift detection. */
  get epoch(): number {
    return Number(this.state.groupContext.epoch);
  }

  /**
   * The ciphersuite this group is actually running. Persist this with the state
   * and pass it back on load: an MLS group's suite is fixed for life, so it must
   * survive app updates that change the build's default suite.
   */
  get ciphersuite(): string {
    return this.cs.name;
  }

  /** Serialize the full group state (ratchet tree + secrets) for local at-rest storage. */
  serialize(): string {
    return bytesToBase64(encodeGroupState(this.state));
  }

  /** Refresh roster-backed credential validation after membership changes. */
  setAuthenticationService(authService: AuthenticationService): void {
    this.state.clientConfig.authService = authService;
  }

  /**
   * Re-hydrate a copy of an existing client bound to a fresh credential
   * validator (used for commit previews computed on a disposable snapshot).
   *
   * Uses the SOURCE client's own ciphersuite. The previous code re-decoded with
   * the build's current default suite, which silently produced a client whose
   * impl did not match its own ratchet state — i.e. it broke every group that
   * outlived a ciphersuite change.
   */
  static cloneWithValidator(
    source: MlsGroupClient,
    authService?: AuthenticationService,
  ): MlsGroupClient {
    return MlsGroupClient.deserialize(source.serialize(), source.cs, authService);
  }

  static deserialize(
    b64: string,
    cs: CiphersuiteImpl,
    authService?: AuthenticationService,
  ): MlsGroupClient {
    const decoded = decodeGroupState(base64ToBytes(b64), 0);
    if (!decoded) throw new Error('mls: failed to decode group state');
    // decodeGroupState yields GroupState; re-attach clientConfig (the
    // ClientState augmentation that encodeGroupState does not persist).
    const state = decoded[0] as ClientState;
    state.clientConfig = mlsClientConfig(authService);
    return new MlsGroupClient(state, cs);
  }

  private static async loadCs(): Promise<CiphersuiteImpl> {
    const suite = getCiphersuiteFromName(CIPHERSUITE_NAME);
    return getCiphersuiteImpl(suite, nobleCryptoProvider);
  }

  /**
   * Generate a fresh key package pair for THIS device (used to join / be added).
   * When `identityKeyPair` is supplied, the leaf's signature key is bound to the
   * device's long-term Ed25519 identity key (mourn layer); otherwise a fresh
   * throwaway signature key is generated (test/legacy path).
   */
  static async generateKeyPackagePair(
    deviceId: string,
    identityKeyPair?: MlsIdentityKeyPair,
  ): Promise<MlsKeyPackagePair> {
    const cs = await MlsGroupClient.loadCs();
    const { publicPackage, privatePackage } = identityKeyPair
      ? await generateKeyPackageWithKey(
          mlsCredential(deviceId),
          mlsCapabilities(),
          mlsLifetime(),
          mlsExtensions(),
          toMlsSignatureKey(identityKeyPair),
          cs,
        )
      : await generateKeyPackage(
          mlsCredential(deviceId),
          mlsCapabilities(),
          mlsLifetime(),
          mlsExtensions(),
          cs,
        );
    const wire: MLSMessage = {
      version: 'mls10',
      wireformat: 'mls_key_package',
      keyPackage: publicPackage,
    };
    return {
      publicPackageB64: bytesToBase64(encodeMlsMessage(wire)),
      privatePackage,
    };
  }

  /**
   * Create a brand-new group as the creator (sole initial member initially).
   * @param groupId raw bytes (stable, non-secret id, e.g. server group uuid)
   * @param deviceId the creator's device id (leaf identity); defaults to the
   *                 decoded group id for the legacy/test path.
   * @param identityKeyPair optional long-term Ed25519 identity key to bind the
   *                        creator leaf to (mourn layer).
   */
  static async create(
    groupId: Uint8Array,
    deviceId?: string,
    identityKeyPair?: MlsIdentityKeyPair,
    authService?: AuthenticationService,
  ): Promise<{ client: MlsGroupClient; keyPackagePair: MlsKeyPackagePair }> {
    const cs = await MlsGroupClient.loadCs();
    const credentialIdentity = deviceId ?? new TextDecoder().decode(groupId);
    const { publicPackage, privatePackage } = identityKeyPair
      ? await generateKeyPackageWithKey(
          mlsCredential(credentialIdentity),
          mlsCapabilities(),
          mlsLifetime(),
          mlsExtensions(),
          toMlsSignatureKey(identityKeyPair),
          cs,
        )
      : await generateKeyPackage(
          mlsCredential(credentialIdentity),
          mlsCapabilities(),
          mlsLifetime(),
          mlsExtensions(),
          cs,
        );
    const clientState = (await createGroup(
      groupId,
      publicPackage,
      privatePackage,
      mlsExtensions(),
      cs,
      mlsClientConfig(authService),
    )) as ClientState;
    const client = new MlsGroupClient(clientState, cs);
    const kpWire: MLSMessage = {
      version: 'mls10',
      wireformat: 'mls_key_package',
      keyPackage: publicPackage,
    };
    return {
      client,
      keyPackagePair: {
        publicPackageB64: bytesToBase64(encodeMlsMessage(kpWire)),
        privatePackage,
      },
    };
  }

  /** Join a group from a Welcome message (base64) + our key package pair. */
  static async join(
    welcomeB64: string,
    keyPackage: KeyPackage,
    privatePackage: PrivateKeyPackage,
    authService?: AuthenticationService,
  ): Promise<MlsGroupClient> {
    const decoded = decodeMls(base64ToBytes(welcomeB64));
    if (decoded.wireformat !== 'mls_welcome') throw new Error('mls: expected welcome message');
    const welcome = (decoded as MlsWelcome).welcome;
    // Join with the WELCOME'S ciphersuite, not the build default: a welcome for
    // a group created before the ChaCha20 switch is an AES-256-GCM group, and
    // joining it with the wrong impl produces a client that cannot read the
    // group's own traffic.
    const cs = await mlsCiphersuite(
      (welcome as { groupInfo?: { groupContext?: { cipherSuite?: unknown } } }).groupInfo
        ?.groupContext?.cipherSuite,
    );
    const clientState = (await joinGroup(
      welcome,
      keyPackage,
      privatePackage,
      emptyPskIndex,
      cs,
      undefined,
      undefined,
      mlsClientConfig(authService),
    )) as ClientState;
    return new MlsGroupClient(clientState, cs);
  }

  /** Encrypt a chat message. Advances local ratchet — caller MUST persist serialize(). */
  async encrypt(content: string): Promise<string> {
    const { newState, privateMessage } = await createApplicationMessage(
      this.state,
      new TextEncoder().encode(content),
      this.cs,
    );
    this.state = newState;
    const wire: MLSMessage = {
      version: 'mls10',
      wireformat: 'mls_private_message',
      privateMessage,
    };
    return bytesToBase64(encodeMlsMessage(wire));
  }

  /** Decrypt an inbound application message (base64). Advances ratchet. */
  async decrypt(ciphertextB64: string): Promise<string> {
    const decoded = decodeMls(base64ToBytes(ciphertextB64));
    if (decoded.wireformat !== 'mls_private_message') {
      throw new Error('mls: expected private application message');
    }
    const pm: PrivateMessage = (decoded as MlsPrivateMessage).privateMessage;
    const result = await processPrivateMessage(this.state, pm, emptyPskIndex, this.cs);
    if (result.kind !== 'applicationMessage') {
      throw new Error('mls: expected application message, got commit/proposal');
    }
    this.state = result.newState;
    return new TextDecoder().decode(result.message);
  }

  /**
   * Propose adding one or more members (their public key packages, base64).
   * Produces a single Commit to broadcast + a single Welcome to relay to the
   * new member(s). When `newMemberKeyPackages` has N entries, the commit carries
   * N `add` proposals in ONE epoch and the Welcome's `secrets` array holds one
   * encrypted group-secrets entry per added leaf — each new member extracts its
   * own share by its key-package reference (standard MLS multi-member add).
   *
   * This keeps launch-time onboarding sub-linear: adding K members in one batch
   * is a single commit/epoch that fan-outs to the group, rather than K commits
   * each broadcasting to the whole group.
   *
   * Caller MUST persist serialize() and broadcast both artifacts.
   */
  async addMember(
    newMemberKeyPackages: string | string[],
  ): Promise<{ commitB64: string; welcomeB64: string }> {
    const packages = Array.isArray(newMemberKeyPackages)
      ? newMemberKeyPackages
      : [newMemberKeyPackages];
    if (packages.length === 0) throw new Error('mls: at least one key package is required');
    if (new Set(packages).size !== packages.length) {
      throw new Error('mls: duplicate key package in batch add');
    }

    // Decode every key package up-front so a malformed entry aborts the whole
    // batch BEFORE the commit is created (no partial epoch, no partial state).
    const keyPackages: KeyPackage[] = [];
    for (const b64 of packages) {
      const decoded = decodeMls(base64ToBytes(b64));
      if (decoded.wireformat !== 'mls_key_package') {
        throw new Error('mls: expected key package');
      }
      keyPackages.push((decoded as MlsKeyPackage).keyPackage);
    }

    const commit = await createCommit(
      { state: this.state, cipherSuite: this.cs },
      {
        extraProposals: keyPackages.map((keyPackage) => ({
          proposalType: 'add',
          add: { keyPackage },
        })),
        // Embed the ratchet tree in the Welcome so the new member can join
        // without the server ever seeing/relaying the tree separately.
        ratchetTreeExtension: true,
      },
    );
    this.state = commit.newState;
    return {
      commitB64: bytesToBase64(encodeMlsMessage(commit.commit)),
      welcomeB64: commit.welcome
        ? bytesToBase64(
            encodeMlsMessage({
              version: 'mls10',
              wireformat: 'mls_welcome',
              welcome: commit.welcome,
            } as MLSMessage),
          )
        : '',
    };
  }

  /**
   * Remove a member from the group by their DEVICE id (each device is a
   * separate leaf in the ratchet tree, its credential identity == deviceId).
   *
   * Produces a Remove Commit that, when broadcast to the remaining members and
   * applied by them (via applyCommit), blanks the removed device's leaf and
   * advances the epoch. This makes the removed device's stale ratchet secrets
   * unusable for FUTURE messages — restoring forward secrecy on leave/kick.
   *
   * Caller MUST persist serialize() and broadcast the returned commit.
   * No Welcome is produced (remove does not add anyone).
   */
  async removeMember(deviceId: string): Promise<{ commitB64: string }> {
    const targetIdentity = new TextEncoder().encode(deviceId);
    const tree: RatchetTree = this.state.ratchetTree;

    // Locate the leaf whose basic-credential identity equals this device id.
    // Leave the loop open-tailed: a leaf node sits at even node indices, and
    // the leaf INDEX is nodeIndex / 2 for those positions.
    let removedLeafIndex: number | undefined;
    for (let i = 0; i < tree.length; i++) {
      const node: Node | undefined = tree[i];
      if (!node) continue;
      if (node.nodeType === 'leaf') {
        const cred = node.leaf.credential;
        if (cred?.credentialType === 'basic' && identityEquals(cred.identity, targetIdentity)) {
          // A leaf node sits at even node index i; its MLS leaf index is i/2.
          removedLeafIndex = i / 2;
          break;
        }
      }
    }

    if (removedLeafIndex === undefined) {
      throw new Error(`mls: member device not found in group tree: ${deviceId}`);
    }

    const commit = await createCommit(
      { state: this.state, cipherSuite: this.cs },
      {
        extraProposals: [{ proposalType: 'remove', remove: { removed: removedLeafIndex } }],
        // Remaining members get the updated tree by applying the commit; we do
        // NOT embed the ratchet tree (that is only needed on an add).
        ratchetTreeExtension: false,
      },
    );
    this.state = commit.newState;
    return {
      commitB64: bytesToBase64(encodeMlsMessage(commit.commit)),
    };
  }

  /**
   * Enumerate the DEVICE IDs currently present as leaves in this group's
   * ratchet tree (each leaf's basic-credential identity is the deviceId).
   * Used by the owner to sweep leaves that are no longer in the roster.
   */
  listMemberDeviceIds(): string[] {
    const tree: RatchetTree = this.state.ratchetTree;
    const out: string[] = [];
    for (const node of tree) {
      if (!node || node.nodeType !== 'leaf') continue;
      const cred = node.leaf.credential;
      if (cred?.credentialType === 'basic' && cred.identity.length > 0) {
        out.push(new TextDecoder().decode(cred.identity));
      }
    }
    return out;
  }

  /**
   * Serverless variant of addMember used by tests / offline flows where the
   * new member's key package PAIR is already available locally. Returns the
   * full client the new member would build by joining the Welcome.
   */
  async addMemberLocal(
    newMemberKeyPair: MlsKeyPackagePair,
  ): Promise<{ commitB64: string; memberClient: MlsGroupClient }> {
    const { commitB64, welcomeB64 } = await this.addMember(newMemberKeyPair.publicPackageB64);
    const memberClient = await MlsGroupClient.join(
      welcomeB64,
      await MlsGroupClient.decodeKeyPackage(newMemberKeyPair.publicPackageB64),
      newMemberKeyPair.privatePackage,
    );
    return { commitB64, memberClient };
  }

  /** Decode a wire base64 key package back into a KeyPackage object. */
  static async decodeKeyPackage(b64: string): Promise<KeyPackage> {
    const decoded = decodeMls(base64ToBytes(b64));
    if (decoded.wireformat !== 'mls_key_package') throw new Error('mls: expected key package');
    return (decoded as MlsKeyPackage).keyPackage;
  }

  /** Apply an inbound Commit (base64) from another member. Advances state. */
  async applyCommit(commitB64: string): Promise<void> {
    const msg = decodeMls(base64ToBytes(commitB64));
    if (msg.wireformat === 'mls_private_message') {
      const result = await processPrivateMessage(
        this.state,
        msg.privateMessage,
        emptyPskIndex,
        this.cs,
      );
      this.state = result.newState;
    } else if (msg.wireformat === 'mls_public_message') {
      const result = await processPublicMessage(
        this.state,
        msg.publicMessage,
        emptyPskIndex,
        this.cs,
      );
      this.state = result.newState;
    } else {
      throw new Error(`mls: unsupported commit wireformat ${msg.wireformat}`);
    }
  }
}
